use knownext_storage::LocalApi;
use serde_json::{json,Value};
use std::{fs,path::PathBuf};
#[test]
fn partial_history_prepares_only_a_draft_with_verified_provenance_and_new_save_keeps_old_commits(){
    let temp=tempfile::tempdir().unwrap();let api=LocalApi::new(temp.path().join("state"),"qa".into(),"test".into());let project=api.handle("POST","/api/projects",json!({"name":"Owned partial history","versioningMode":"local-git","syncMode":"none"}),vec![]).unwrap().body;let project_id=project["id"].as_str().unwrap();let root=PathBuf::from(project["folderPath"].as_str().unwrap());let id=format!("{project_id}::Review.md");let route=format!("/api/documents/{id}");let versions_route=format!("/api/projects/{project_id}/versions");
    let historical="# Review\n\nOwner: historical\n\n## Deadline\nTuesday\n";let disk="# Review\n\nOwner: disk\n\n## Deadline\nFriday\n";let local="# Review\n\nOwner: local\n\n## Deadline\nThursday\n";let merged="# Review\n\nOwner: historical\n\n## Deadline\nThursday\n";
    fs::write(root.join("Review.md"),historical).unwrap();let first=api.handle("POST",&versions_route,json!({"documentId":id,"title":"Owned first version"}),vec![]).unwrap().body["version"]["id"].as_str().unwrap().to_string();
    fs::write(root.join("Review.md"),disk).unwrap();let second=api.handle("POST",&versions_route,json!({"documentId":id,"title":"Owned second version"}),vec![]).unwrap().body["version"]["id"].as_str().unwrap().to_string();fs::write(root.join("Unrelated.md"),"Owned unrelated bytes").unwrap();
    let record=api.handle("GET",&route,Value::Null,vec![]).unwrap().body;api.handle("PUT",&format!("{route}/draft"),json!({"markdown":local,"baseFingerprint":record["baseFingerprint"]}),vec![]).unwrap();let review=api.handle("GET",&format!("{route}/versions/{first}/restore-draft"),Value::Null,vec![]).unwrap().body;
    assert_eq!(review["historySource"]["markdown"],historical);assert_eq!(review["diskMarkdown"],disk);let payload=json!({"locationRevision":review["locationRevision"],"diskFingerprint":review["diskFingerprint"],"draftRevision":review["draftRevision"],"localMarkdown":local,"mergedMarkdown":merged,"historySource":{"versionId":first,"markdownSha256":review["historySource"]["markdownSha256"]}});
    let mut bad=payload.clone();bad["historySource"]["markdownSha256"]=json!("wrong");assert!(api.handle("POST",&format!("{route}/conflict"),bad,vec![]).is_err());assert!(!temp.path().join("state/drafts-review").exists());
    assert!(api.handle("GET",&format!("{route}/versions/{}/restore-draft","0".repeat(40)),Value::Null,vec![]).is_err());
    let result=api.handle("POST",&format!("{route}/conflict"),payload.clone(),vec![]).unwrap().body;assert_eq!(fs::read_to_string(root.join("Review.md")).unwrap(),disk);assert_eq!(result["document"]["markdown"],merged);assert_eq!(result["historySource"]["versionId"],first);
    let proposed=result["preservedCopies"][2].as_str().unwrap();let copy:Value=serde_json::from_slice(&fs::read(temp.path().join("state/drafts-review").join(proposed).join("copy.json")).unwrap()).unwrap();assert_eq!(copy["historySource"]["markdown"],historical);assert_eq!(copy["historySource"]["versionId"],first);
    let archives=api.handle("GET","/api/recovery/archives",Value::Null,vec![]).unwrap().body;assert!(archives["items"].as_array().unwrap().iter().any(|row|row["reason"].as_str().unwrap().contains("restauración parcial")));
    assert!(api.handle("POST",&format!("{route}/conflict"),payload,vec![]).is_err());api.handle("PUT",&route,json!({"markdown":merged,"baseFingerprint":result["document"]["baseFingerprint"],"expectedDraftWriteRevision":result["document"]["draftWriteRevision"]}),vec![]).unwrap();let third=api.handle("POST",&versions_route,json!({"documentId":id,"title":"Owned partial restore"}),vec![]).unwrap().body["version"]["id"].as_str().unwrap().to_string();assert_ne!(third,first);assert_ne!(third,second);
    for (version,text) in [(&first,historical),(&second,disk)]{assert_eq!(api.handle("GET",&format!("{route}/versions/{version}/content"),Value::Null,vec![]).unwrap().body["markdown"],text);}assert_eq!(fs::read_to_string(root.join("Unrelated.md")).unwrap(),"Owned unrelated bytes");
}
